476	/**
477	 * Build all personas in a suite for a single output target.
478	 *
479	 * Pipeline:
480	 *   1. Load `_shared.yaml` for the suite
481	 *   2. Load merged partials (shared → suite-local)
482	 *   3. Run `onSuiteInit` on all plugins
483	 *   4. Discover all persona YAML files
484	 *   5. Call `buildPersona()` for each
485	 *
486	 * @param suiteName    Identifier for this suite
487	 * @param suiteConfig  Suite configuration
488	 * @param config       Top-level BuildConfig
489	 * @param plugins      Registered plugins
490	 * @param target       Target output format
491	 * @param agentMap     Pre-built cross-suite agent name map
492	 * @param registry     Target registry to use. Defaults to `defaultRegistry`.
493	 *   **Two-registry limitation:** If you pass a custom `TargetRegistry` only
494	 *   to `build()` (via `config.targetRegistry`) and call `buildSuite()`
495	 *   directly without also passing that registry here, your custom targets
496	 *   will not be visible — `defaultRegistry` will be used instead. Either
497	 *   pass the same registry instance explicitly, or call `build()` to have
498	 *   the registry forwarded automatically.
499	 * @returns            Array of BuildResult objects, one per persona
500	 */

 1	/**
 2	 * tests/builders/persona-builder.test.ts
 3	 *
 4	 * Integration-level tests for the builder core:
 5	 *   - buildPersona()  — single persona pipeline
 6	 *   - buildSuite()    — suite-level discovery + batching
 7	 *   - build()         — top-level entry point with check/strict modes
 8	 *
 9	 * Strategy:
10	 *   - Each test creates a temporary directory tree, populates it with
11	 *     minimal fixture files, and exercises the live builder against it.
12	 *   - The fixtures/ directory in the project root provides a canonical
13	 *     "happy path" suite for positive assertions.
14	 *   - Strict-mode and check-mode tests use ephemeral temp directories.
15	 *
16	 * Acceptance Criteria verified:
17	 *   AC-1: buildPersona() produces correct rendered output for a fixture persona
18	 *   AC-2: buildSuite() processes all discovered personas → BuildResult[]
19	 *   AC-3: build(config) is callable, accepts BuildConfig, returns BuildSummary
20	 *   AC-4: --check mode completes without writing files
21	 *   AC-5: --strict mode throws when any ValidationResult has severity error/warning
22	 *   AC-6: All builder tests pass; TypeScript strict-mode reports zero errors
23	 */
24	
25	import { describe, it, expect, beforeEach, afterEach } from 'vitest';
